// Import Vue, ref, and TanStack Query modules here
import { createApp } from 'vue';
import { ref } from 'vue';
import { QueryClient, useQuery } from '@tanstack/vue-query';

// Create a new QueryClient instance here
const queryClient = new QueryClient();

// Create the main Vue component here
const App = {
  setup() {
    // Create refreshCounter ref here
    const refreshCounter = ref(0);

    // Define the data fetching function here
    const fetchPosts = async () => {
      const response = await fetch('https://jsonplaceholder.typicode.com/posts');
      if (!response.ok) throw new Error('Failed to fetch posts');
      return response.json();
    };

    // Call useQuery here
    const { data, isLoading } = useQuery({
      queryKey: ['posts', refreshCounter],
      queryFn: fetchPosts
    });

    // Define the manual refresh handler here
    const handleRefresh = () => {
      refreshCounter.value++;
    };

    return {
      // Expose refreshCounter to template
      refreshCounter,
      data,
      isLoading,
      handleRefresh
    };
  },
  template: `
    <div>
      <!-- Add loading message paragraph here -->
      <button @click="handleRefresh">Refresh Posts</button>
      <div v-if="data">
        <h2>Posts ({{ data.length }})</h2>
        <ul>
          <li v-for="post in data.slice(0, 5)" :key="post.id">
            {{ post.title }}
          </li>
        </ul>
      </div>
    </div>
  `
};
